const crypto = require('crypto');
const env = (name) => $env[name];

function header(headers, name) {
  const match = Object.entries(headers || {}).find(([key]) => key.toLowerCase() === name.toLowerCase());
  return Array.isArray(match?.[1]) ? match[1][0] : match?.[1];
}

function safeCompare(a, b) {
  const left = Buffer.from(String(a || ''));
  const right = Buffer.from(String(b || ''));
  return left.length === right.length && crypto.timingSafeEqual(left, right);
}

const item = $input.first();
const expectedSecret = env('STANDUP_INTERNAL_SECRET') || env('LOCAL_WORKER_SECRET');
const providedSecret = header(item.json.headers, 'x-poc-standup-secret');

if (!expectedSecret) {
  throw new Error('STANDUP_RECEIVED failed: STANDUP_INTERNAL_SECRET or LOCAL_WORKER_SECRET is not configured');
}

if (!safeCompare(expectedSecret, providedSecret)) {
  console.log(JSON.stringify({ stage: 'STANDUP_RECEIVED', authorized: false }));
  return [{ json: { authorized: false, ackStatusCode: 403, ackText: 'forbidden' } }];
}

const payload = item.json.body || {};
console.log(
  JSON.stringify({
    stage: 'STANDUP_RECEIVED',
    authorized: true,
    correlationId: payload.correlation_id,
    dryRun: Boolean(payload.dry_run),
  }),
);

return [
  {
    json: {
      authorized: true,
      ackStatusCode: 202,
      ackText: 'accepted',
      correlationId: String(payload.correlation_id || ''),
      dryRun: Boolean(payload.dry_run),
      transcript: String(payload.transcript || ''),
      slackChannelId: String(payload.slack_channel_id || ''),
      slackMessageTs: String(payload.slack_message_ts || ''),
      slackThreadTs: String(payload.slack_thread_ts || ''),
      requesterIdentity: String(payload.requester_identity || ''),
      slackEventId: String(payload.slack_event_id || ''),
    },
  },
];

const env = (name) => $env[name];
const https = require('https');
const http = require('http');

function requiredEnv(names) {
  const missing = names.filter((name) => !env(name));
  if (missing.length) throw new Error(`Missing environment variable(s): ${missing.join(', ')}`);
}

async function httpRequest(url, options = {}) {
  const method = options.method || 'GET';
  const body = options.body || '';
  const headers = { ...(options.headers || {}) };
  if (body && !headers['Content-Length']) headers['Content-Length'] = Buffer.byteLength(body);
  const client = url.startsWith('https:') ? https : http;

  return await new Promise((resolve, reject) => {
    const request = client.request(url, { method, headers }, (response) => {
      const chunks = [];
      response.on('data', (chunk) => chunks.push(Buffer.from(chunk)));
      response.on('end', () => {
        const status = response.statusCode || 0;
        resolve({
          status,
          ok: status >= 200 && status < 300,
          headers: response.headers,
          bodyText: Buffer.concat(chunks).toString('utf8'),
        });
      });
    });
    request.on('error', reject);
    request.setTimeout(Number(env('STANDUP_ANALYSIS_HTTP_TIMEOUT_MS') || 240000), () =>
      request.destroy(new Error(`HTTP ${method} ${url} timed out`)),
    );
    if (body) request.write(body);
    request.end();
  });
}

const input = $input.first().json;
if (!input.authorized) return [{ json: input }];

try {
  requiredEnv(['LOCAL_WORKER_URL', 'LOCAL_WORKER_SECRET']);
  if (!input.transcript.trim()) throw new Error('Transcript is empty');

  const workerUrl = `${env('LOCAL_WORKER_URL').replace(/\/$/, '')}/poc/standup/analyze`;
  const response = await httpRequest(workerUrl, {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      'x-poc-worker-secret': env('LOCAL_WORKER_SECRET'),
    },
    body: JSON.stringify({
      correlation_id: input.correlationId,
      dry_run: input.dryRun,
      transcript: input.transcript,
      slack_channel_id: input.slackChannelId,
      slack_message_ts: input.slackMessageTs,
      slack_thread_ts: input.slackThreadTs,
      requester_identity: input.requesterIdentity,
    }),
  });

  if (!response.ok) {
    throw new Error(`Local standup analyzer failed (${response.status}): ${response.bodyText.slice(0, 900)}`);
  }

  const analysis = response.bodyText ? JSON.parse(response.bodyText) : {};
  console.log(
    JSON.stringify({
      stage: 'TRANSCRIPT_PARSED',
      correlationId: input.correlationId,
      issueCount: Array.isArray(analysis.issues) ? analysis.issues.length : 0,
    }),
  );

  return [{ json: { ...input, analysis } }];
} catch (error) {
  return [
    {
      json: {
        ...input,
        standupFailed: true,
        failureStage: 'TRANSCRIPT_PARSED',
        errorMessage: String(error.message || error).slice(0, 1200),
      },
    },
  ];
}

const input = $input.first().json;
if (!input.authorized || input.standupFailed) return [{ json: input }];

function normalizeState(value) {
  const state = String(value || 'clarification').toLowerCase().replace(/[\s-]+/g, '_');
  if (['in_progress', 'review', 'done', 'blocked', 'no_change', 'clarification'].includes(state)) return state;
  return 'clarification';
}

function normalizeConfidence(value) {
  const confidence = String(value || 'low').toLowerCase();
  if (['high', 'medium', 'low'].includes(confidence)) return confidence;
  return 'low';
}

try {
  const issues = input.analysis?.issues;
  if (!Array.isArray(issues)) throw new Error('Claude analysis did not contain an issues array');

  const seen = new Set();
  const actionPlan = [];
  for (const issue of issues.slice(0, 50)) {
    const issueKey = String(issue.issueKey || '').toUpperCase().trim();
    if (!/^SYSCO-\d+$/.test(issueKey) || seen.has(issueKey)) continue;
    seen.add(issueKey);

    const confidence = normalizeConfidence(issue.confidence);
    const desiredState = normalizeState(issue.desiredState);
    actionPlan.push({
      issueKey,
      evidence: String(issue.evidence || '').slice(0, 500),
      summary: String(issue.summary || '').slice(0, 500),
      desiredState,
      addComment: Boolean(issue.addComment) && confidence !== 'low',
      comment: String(issue.comment || issue.summary || '').slice(0, 800),
      confidence,
    });
  }

  console.log(JSON.stringify({ stage: 'ACTION_PLAN_CREATED', correlationId: input.correlationId, issueCount: actionPlan.length }));
  return [{ json: { ...input, actionPlan } }];
} catch (error) {
  return [
    {
      json: {
        ...input,
        standupFailed: true,
        failureStage: 'ACTION_PLAN_CREATED',
        errorMessage: String(error.message || error).slice(0, 1200),
      },
    },
  ];
}

